window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"XWhrppwTa9M","speaker":"Denis Bećirović","role":"Chairman of the Presidency","country":"Bosnia and Herzegovina","region":"Europe","url":"https://www.youtube.com/watch?v=XWhrppwTa9M","date":"20260922","title":"🇧🇦 Bosnia and Herzegovina - Chairman of the Presidency Addresses UN General Debate, 81st Session","seconds":813,"words":1441,"counts":{"claims":20,"promises":0,"attacks":7},"topics":[{"topic":"Srebrenica","share":0.0961,"seconds":78},{"topic":"Bosnia and Herzegovina","share":0.0941,"seconds":76},{"topic":"Serbia war crimes","share":0.0876,"seconds":71},{"topic":"Republika Srpska","share":0.0873,"seconds":71},{"topic":"Bosnia and Herzegovina EU","share":0.0832,"seconds":68},{"topic":"Climate change","share":0.0828,"seconds":67},{"topic":"Bosnia and Herzegovina sovereignty","share":0.0821,"seconds":67},{"topic":"UN reform","share":0.081,"seconds":66},{"topic":"Bosnia and Herzegovina war crimes","share":0.0777,"seconds":63},{"topic":"Ukraine","share":0.0771,"seconds":63},{"topic":"Gaza","share":0.0758,"seconds":62},{"topic":"International law","share":0.0753,"seconds":61}],"timeline":[[5,82,"Bosnia and Herzegovina"],[84,151,"Bosnia and Herzegovina EU"],[153,216,"Bosnia and Herzegovina war crimes"],[218,280,"Ukraine"],[281,343,"Gaza"],[344,410,"UN reform"],[411,473,"International law"],[474,542,"Climate change"],[543,622,"Srebrenica"],[623,694,"Serbia war crimes"],[696,767,"Republika Srpska"],[769,836,"Bosnia and Herzegovina sovereignty"],[837,881,null]],"stances":{"Bosnia and Herzegovina":"Denis Bećirović states that Bosnia and Herzegovina is a nation that has survived severe trials while maintaining its path toward a better future.","Bosnia and Herzegovina EU":"Denis Bećirović states that Bosnia and Herzegovina is pursuing membership in the European Union and NATO as strategic objectives despite ongoing obstruction.","Bosnia and Herzegovina war crimes":"Denis Bećirović states that UN courts have established the aggression against Bosnia as an international armed conflict involving genocide and joint criminal enterprises aimed at destroying the state.","Ukraine":"Denis Bećirović states that the international community failed to respond adequately to the Russian Federation's aggression against Ukraine and compares this inaction to the lack of response during the aggression against Bosnia and Herzegovina.","Gaza":"Denis Bećirović argues that the erosion of international law is a shared root cause of global crises, including the situation in Gaza, and asserts that force cannot bring progress.","UN reform":"Denis Bećirović argues that the UN Charter must be reaffirmed and the organization revitalized to counter weakening international trust caused by actors undermining its values.","International law":"Denis Bećirović calls for UN member states to focus on reaffirming relations based on international law and promoting peace, human rights, and social progress.","Climate change":"Denis Bećirović states that Bosnia and Herzegovina is aware of climate change and committed to contributing to global efforts, including the transition to renewable energy and reducing emissions.","Srebrenica":"Denis Bećirović asserts that the UN resolution commemorating the 1995 Srebrenica genocide is a moral act and condemns Serbia for glorifying convicted war criminal Ratko Mladić.","Serbia war crimes":"Denis Bećirović asserts that Serbia's institutional glorification of a convicted war criminal represents an anti-civilizational act and indicates the state has not abandoned genocidal policies.","Republika Srpska":"Denis Bećirović asserts that the current leadership of Republika Srpska continues to threaten peace and security while attempting to destroy the Dayton Peace Agreement.","Bosnia and Herzegovina sovereignty":"Denis Bećirović asserts that Bosnia and Herzegovina is an unconquerable state with a historical presence in Southeast Europe and expresses pride in its people."},"claims":[{"t":72,"quote":"We are a symbol of a nation that has survived severe trials but has not lost its path towards a better future.","topic":"Bosnia and Herzegovina","kind":"fact"},{"t":84,"quote":"In the period from 1992 to 1995, my country was subjected to aggression, joint criminal enterprises, genocide against Bosnjaks, crimes against humanity, and other war crimes.","topic":"Bosnia and Herzegovina EU","kind":"fact"},{"t":124,"quote":"Today, Bosnia Intersegoina stands at the doorstep of the European Union and the NATO.","topic":"Bosnia and Herzegovina EU","kind":"fact"},{"t":166,"quote":"It is very important that the UN courts have established the nature of the war waged against the Republic of Bosnia and Hergoina.","topic":"Bosnia and Herzegovina war crimes","kind":"fact"},{"t":178,"quote":"Final judgments, including those concerning joint criminal enterprises, have established that this was an international armed conflict.","topic":"Bosnia and Herzegovina war crimes","kind":"fact"},{"t":190,"quote":"Judgments of the highest UN courts have established that genocide was committed against Bosnjaks.","topic":"Bosnia and Herzegovina war crimes","kind":"fact"},{"t":229,"quote":"the aggression against Ukraine, the suffering in Gaza, the war in the Gulf region, the catastrophic situation in Sudan","topic":"Ukraine","kind":"fact"},{"t":255,"quote":"The world did not respond adequately to the aggression against Ukraine and the genocide against Palestinians in Gaza, just as it did not during the aggression against Bosnia and Hergoina","topic":"Ukraine","kind":"fact"},{"t":281,"quote":"While Gaza is humanity's greatest defeat in the 21st the greatest global crisis are directly interconnected and have the same route. The erosion of international law.","topic":"Gaza","kind":"fact"},{"t":318,"quote":"The politics of force cannot bring progress to Instead of force, we need respect and the strengthening of the existing international norms, rules and institutions that we have built over more than 80 years.","topic":"Gaza","kind":"fact"},{"t":344,"quote":"Trust is weakening because some actors in the international community undermine the values enshrined in the UN charter.","topic":"UN reform","kind":"fact"},{"t":495,"quote":"Bosnia and Segoina is a reliable and responsible member of the United Nations.","topic":"Climate change","kind":"fact"},{"t":503,"quote":"I would like to remind that Bosnia desergoina is aware of climate change and committed to contributing to global efforts, committed to the transition towards renewable energy sources and the reduction of harmful gas emissions","topic":"Climate change","kind":"fact"},{"t":563,"quote":"Bosnia and Herzgoina is the only country in Europe where genocide was committed after the Second World War.","topic":"Srebrenica","kind":"fact"},{"t":571,"quote":"In May 2024, the UN General Assembly adopted the resolution designating 11th July as the International Day of Reflection and Commemoration of the 1995 genocide in Sreita.","topic":"Srebrenica","kind":"fact"},{"t":652,"quote":"It is a direct assault on the values of the United Nations whose court delivered a final judgment against this war criminal.","topic":"Serbia war crimes","kind":"fact"},{"t":663,"quote":"Let me remind you that Serbia is the only state in the world that has been found by a UN court to have violated the UN convention on the prevention and punishment of the crime of genocide.","topic":"Serbia war crimes","kind":"number"},{"t":697,"quote":"the ideology and policies that led to genocide against Bosnjaks continue to threaten Bosnia","topic":"Republika Srpska","kind":"fact"},{"t":727,"quote":"The victims of the genocide and the employees of the memorial centers Reberita are facing unacceptable pressures from the police of the Republic Serpska","topic":"Republika Srpska","kind":"fact"},{"t":807,"quote":"There is not a single map of southeast Europe from the past 1,000 years on which Bosnia or Bosnia and Suggoina does not appear.","topic":"Bosnia and Herzegovina sovereignty","kind":"fact"}],"promises":[],"attacks":[{"t":101,"quote":"Following the end of the aggression in destructive forces have sought through blockades, obstruction, and other means to halt the progress of Bosnia and They are slowing down our path towards a modern European state","topic":"Bosnia and Herzegovina EU","target":"Unnamed opponents"},{"t":142,"quote":"Unfortunately, there are still those seeking to realize greater state projects at the expense of the territory of Bosnia and Hergoina.","topic":"Bosnia and Herzegovina EU","target":"Separatist groups"},{"t":616,"quote":"The monster Rat Kumladic is not a hero but a convicted war criminal.","topic":"Srebrenica","target":"Ratko Mladić"},{"t":623,"quote":"The institutional glorification of this war criminal is an anti-ivilizational and unacceptable act. It amounts to identifying Serbia's state leadership with one of the worst butchers in European history.","topic":"Serbia war crimes","target":"Serbian government"},{"t":712,"quote":"current leadership of the Bosnian entity, continues to threaten the peace and security of Bosnian Duggoina and the region","topic":"Republika Srpska","target":"Bosnian Serb leadership"},{"t":741,"quote":"police and other institutions of Republica Serpska which committed the genocide against today threaten the survivors","topic":"Republika Srpska","target":"Bosnian Serb security forces"},{"t":756,"quote":"Those seeking to destroy the Dayton peace agreement are attempting to create the conditions for the secession of the Bosnian entity Republicska","topic":"Republika Srpska","target":"Opponents of the Dayton Agreement"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":5,"topic":"Bosnia and Herzegovina","text":"The assembly will hear an address by his excellency Denise Biroich, chairman of the presidency of Bosnaguia. I request protocol to escort his excellency and invite him to address the Dear President of the United Nations General Assembly, respected Secretary General of the United Nations, ladies and gentlemen, it is an honor and a pleasure to address the 81st session of the UN General Assembly on behalf of Bosnia and We are a symbol of a nation that has survived severe trials but has not lost its path towards a better future."},{"t":84,"topic":"Bosnia and Herzegovina EU","text":"In the period from 1992 to 1995, my country was subjected to aggression, joint criminal enterprises, genocide against Bosnjaks, crimes against humanity, and other war crimes. Following the end of the aggression in destructive forces have sought through blockades, obstruction, and other means to halt the progress of Bosnia and They are slowing down our path towards a modern European state, but they cannot stop it. Today, Bosnia Intersegoina stands at the doorstep of the European Union and the NATO. These are our strategic foreign policy objectives unanimously defined by the state authorities of Bosnia and Unfortunately, there are still those seeking to realize greater state projects at the expense of the territory of Bosnia and Hergoina."},{"t":153,"topic":"Bosnia and Herzegovina war crimes","text":"During the aggression they attacked our country by military means today they do so by political, diplomatic and other means. It is very important that the UN courts have established the nature of the war waged against the Republic of Bosnia and Hergoina. Final judgments, including those concerning joint criminal enterprises, have established that this was an international armed conflict. Judgments of the highest UN courts have established that genocide was committed against Bosnjaks. They also stand as judgments on the greater state policies that through a joint criminal enterprise sought to divide and destroy Bosnian as an independent, sovereign, indivisible and internationally recognized state."},{"t":218,"topic":"Ukraine","text":"Ladies and gentlemen, we live in a world of injustice, insecurity, and intolerance. the strengthening of authoritarian populism, the aggression against Ukraine, the suffering in Gaza, the war in the Gulf region, the catastrophic situation in Sudan, and other flash points have brought humanity into a profound crisis marked by great uncertainty and fear. We must not remain silent in the face of The world did not respond adequately to the aggression against Ukraine and the genocide against Palestinians in Gaza, just as it did not during the aggression against Bosnia and Hergoina. The aggression of the Russian Federation against Ukraine is a flagrant example of a violation of the UN charter and international law."},{"t":281,"topic":"Gaza","text":"While Gaza is humanity's greatest defeat in the 21st the greatest global crisis are directly interconnected and have the same route. The erosion of international law. Disrespect for international law cannot lead the world towards prosperity and a better future. Ladies and gentlemen, without identifying the causes of the crisis facing contemporary humanity, we cannot solve its problems. The politics of force cannot bring progress to Instead of force, we need respect and the strengthening of the existing international norms, rules and institutions that we have built over more than 80 years. The multilateral system today faces a serious challenge, a crisis of institutional trust."},{"t":344,"topic":"UN reform","text":"Trust is weakening because some actors in the international community undermine the values enshrined in the UN charter. The future of humanity does not lie in policies of violence and human rights Conflicts and wars are not the purpose of our civilization. Let us build a culture of dialogue, cooperation and peace. In this context, I believe it is of utmost importance to reaffirm the importance of the UN charter, revitalize the role of the UN as the global center for coordination and cooperation. Support the reform process and strengthen the credibility of the United Nations. Consistently implement the sustainable development goals. build mutual trust, inclusiveness and democratic vision of leadership and strengthen preventive diplomacy at a time of numerous tensions and conflicts."},{"t":411,"topic":"International law","text":"Let respect for international law, peace, solidarity, sustainable development and justice be the path that we follow together. Ladies and gentlemen, we in Bosnia and Herzgoina call upon all UN member states to focus on reaffirming relations between states on the basis of international law, ensuring respect for human rights and fundamental freedoms, promoting peace and social progress, combating hate speech and all forms of discrimination, strengthening policies for the prevention of genocide, crimes against humanity and other war crimes, advancing the rights of women and children, and strengthening gender equality, better health care and The world must return to the fundamental principles upon which the UN is founded."},{"t":474,"topic":"Climate change","text":"Respect for human dignity, the sovereign equality of states, the peaceful settlement of disputes, respect for international law. These are not unrealistic propositions. They are the only possible foundations of a stable world. Bosnia and Segoina is a reliable and responsible member of the United Nations. Among other things, I would like to remind that Bosnia desergoina is aware of climate change and committed to contributing to global efforts, committed to the transition towards renewable energy sources and the reduction of harmful gas emissions and determined to combat all forms of We in Bosnia desergoina know that peace cannot be taken for granted. Peace. Peace must be safeguarded every day. It requires responsibility of political leaders, respect for the law and readiness for dialogue."},{"t":543,"topic":"Srebrenica","text":"There must not be one standard for large states and another for small states. If we want to preserve trust in the international order, the rules we establish together must be applied Ladies and gentlemen, Bosnia and Herzgoina is the only country in Europe where genocide was committed after the Second World War. In May 2024, the UN General Assembly adopted the resolution designating 11th July as the International Day of Reflection and Commemoration of the 1995 genocide in Sreita. This resolution represents a profoundly moral and civilizational act by the UN General Assembly. The adopted resolution is equally important for the UN and for Bosnia and Hergoina. It is particularly dangerous that the leadership of the Republic of Serbia glorifies the convicted war criminal Rat The monster Rat Kumladic is not a hero but a convicted war criminal."},{"t":623,"topic":"Serbia war crimes","text":"The institutional glorification of this war criminal is an anti-ivilizational and unacceptable act. It amounts to identifying Serbia's state leadership with one of the worst butchers in European history. It is an indication that Serbia has not abandoned the ideology and policies that lead to aggression and genocide. It is a direct assault on the values of the United Nations whose court delivered a final judgment against this war criminal. Let me remind you that Serbia is the only state in the world that has been found by a UN court to have violated the UN convention on the prevention and punishment of the crime of genocide. I call on the United Nations and European Union and other international actors to clearly condemn this conduct and take concrete measures against those who institutionally glorify convicted war criminals."},{"t":696,"topic":"Republika Srpska","text":"Unfortunately, the ideology and policies that led to genocide against Bosnjaks continue to threaten Bosnia and From the podium of the UN General Assembly, I wish to publicly warn the international public that the current leadership of the Bosnian entity, continues to threaten the peace and security of Bosnian Duggoina and the region. We must stop this destructive policy together. The victims of the genocide and the employees of the memorial centers Reberita are facing unacceptable pressures from the police of the Republic Serpska. We must not allow that the police and other institutions of Republica Serpska which committed the genocide against today threaten the survivors and those that are preserving the memory on the victims of the genocide. Those seeking to destroy the Dayton peace agreement are attempting to create the conditions for the secession of the Bosnian entity Republicska."},{"t":769,"topic":"Bosnia and Herzegovina sovereignty","text":"In the period ahead, they will intensify their activities primarily with the aim of weakening and abolishing the mandate of the high representative of the international community which is also envisaged by the daton peace agreement, weakening the institution of the constitutional court of Bosnian dergoina and seizing the state property of Bosnian deruggoina contrary to the national and international law. Ladies and gentlemen, Bosnia and Herzgoina is an unconquerable state. There is not a single map of southeast Europe from the past 1,000 years on which Bosnia or Bosnia and Suggoina does not appear. Bosnia and Dergoina is home to people who love freedom more than their own lives. Finally, as the chairman of the presidency of Bosian desergoina, I wish to emphasize that I'm proud of the brave people of Bosian Suggoina."},{"t":837,"topic":null,"text":"These are people who have suffered injustice, yet they continue to fight for justice. These are people who have been victims of lies, yet they continue to fight for the truth. These are people who support the struggle for justice, freedom, and human dignity throughout the world. These are the honorable and proud people of my homeland, Bosnia and Herzgoina. Thank you for your attention. On behalf of the assembly, I wish thank the chairman of the presidency of Bosnia and Heriggoia"}],"compare":[{"topic":"Bosnia and Herzegovina","share":0.1598,"mean":0.0007,"rank":1,"others":1},{"topic":"Serbia","share":0.0876,"mean":0.0006,"rank":1,"others":2},{"topic":"Climate Change","share":0.0828,"mean":0.0426,"rank":40,"others":77},{"topic":"UN & its reform","share":0.081,"mean":0.2054,"rank":156,"others":170},{"topic":"Russia-Ukraine War","share":0.0771,"mean":0.0351,"rank":31,"others":44},{"topic":"Israel–Palestine","share":0.0758,"mean":0.0523,"rank":48,"others":76},{"topic":"International Law & Order","share":0.0753,"mean":0.0603,"rank":62,"others":102}]};
